# Oficina gestiona los vehículos desde la web. Los oficiales y peones no necesitan permisos:
# la vista les deja ver y apuntar solo en el vehículo del que son responsables
MODELOS = ['vehiculo', 'kilometraje', 'revisionvehiculo', 'notavehiculo']
PERMISOS_OFICINA = [f'{accion}_{modelo}' for modelo in MODELOS for accion in ('view', 'add', 'change', 'delete')]


def permisos_oficina(apps, schema_editor):
    for config in apps.get_app_configs():
        config.models_module = True
        create_permissions(config, apps=apps, verbosity=0)
        config.models_module = None
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    oficina = Group.objects.filter(name='Oficina').first()
    if oficina:
        oficina.permissions.add(*Permission.objects.filter(content_type__app_label='gestion', codename__in=PERMISOS_OFICINA))


